-- SELECT de metadados apenas. Não executa RPCs de negócio nem lê usuários/tokens.
select jsonb_build_object(
 'auth_columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type)) from information_schema.columns where table_schema='auth' and ((table_name='users' and column_name in ('id','email_confirmed_at')) or (table_name='sessions' and column_name in ('id','user_id','not_after')))),
 'profile_signup_role_present',exists(select 1 from information_schema.columns where table_schema='public' and table_name='profiles' and column_name='signup_role'),
 'contracts',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'search_path',p.proconfig,'authenticated_execute',has_function_privilege('authenticated',p.oid,'execute'),'anon_execute',has_function_privilege('anon',p.oid,'execute'))),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='public' and p.proname in ('get_my_account_profile','complete_my_profile','request_account_deletion','discover_vendors','get_my_interest_state','create_purchase_intent','cancel_purchase_intent')) or (n.nspname='private' and p.proname in ('push_actor_session','push_projection','confirmed_actor'))),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'trigger',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and ((n.nspname='auth' and c.relname='users') or (n.nspname='public' and c.relname in ('vendor_routes','purchase_intents')))),
 'private_tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'authenticated_select',has_table_privilege('authenticated',c.oid,'select'),'anon_select',has_table_privilege('anon',c.oid,'select'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('interest_push_progress','account_deletion_requests'))
) as audit;
